SELECT oor.return_cash,oob.shop_id,oob.shop_name, oor.order_id, oor.return_code, oor.return_type, oor.return_add_time, oor.return_state, oor.return_payment_voucher, oor.order_goods_num,oob.buyer_user_id as buyUserId,oob.buyer_user_id as buyUserName, oor.return_method_status,orp.intervention_state,oor.expiration_time,orp.processing_results,sb.shop_self_support FROM ${database.prefix.order}hou_order_return oor LEFT join ${database.prefix.order}hou_order_base oob on oob.order_id = oor.order_id left join ${database.prefix.order}hou_order_return_platform orp on oor.order_id = orp.order_id left join ${database.prefix.supplier}hou_shop_base sb on sb.supplier_shop_id = oor.shop_id WHERE oob.original_order is null
and oob.buyer_user_id in
#{item}
and oor.return_type = #{param.returnType}
and oor.return_add_time between #{param.returnAddTime} and #{param.returnFinishTime}
and oor.return_code LIKE CONCAT('%', #{param.returnCode},'%')
and oor.order_id LIKE CONCAT('%', #{param.orderId},'%')
ORDER BY oor.return_add_time desc

SELECT oor.return_state,oor.return_code, oor.return_cash, oor.return_commision_fee, oor.return_reason,
oor.return_add_time,
oor.return_shop_message, oor.return_shop_time ,oor.order_id, oor.buyer_user_account,
gmsb.shop_name, oob.payment_name, oob.payment_number,
oob.order_payment_amount,oob.payment_time,oor.order_operator,oor.order_operator_time
FROM ${database.prefix.order}hou_order_base oob left join ${database.prefix.order}hou_order_return oor on oob.order_id = oor.order_id
left join ${database.prefix.supplier}hou_shop_base gmsb on oor.shop_id = gmsb.supplier_shop_id
where oor.return_type = 1


        and oor.return_state = #{param.returnState}


        and oor.return_state = 3



    and oor.return_code like CONCAT('%',#{param.returnCode},'%')


    and oor.shop_name like CONCAT('%',#{param.shopName},'%')


    and oob.payment_time >= #{param.payStartTime}


    and oob.payment_time <= #{param.payFinishTime}


    and oor.buyer_user_account like CONCAT('%',#{param.buyerUserAccount},'%')


    and oor.order_id like CONCAT('%',#{param.orderId},'%')


    and oor.return_add_time >= #{param.returnStartTime}


    and oor.return_add_time <= #{param.returnFinishTime}


    and oor.return_cash >= #{param.returnMinCash}


    and oor.return_cash <= #{param.returnMaxCash}

order by oor.return_add_time desc

SELECT oor.return_code, oor.return_cash, oor.return_commision_fee, oor.return_reason, oor.return_add_time,
oor.return_shop_message, oor.return_shop_time ,oor.order_id, oor.buyer_user_account,
oor.shop_name, oob.payment_name,oob.payment_time, oob.payment_number, oob.order_payment_amount,oor.return_state
FROM ${database.prefix.order}hou_order_base oob,${database.prefix.order}hou_order_return oor
where oor.return_type = 1

    and oor.return_state = #{param.returnState}


    and oor.return_code = #{param.returnCode}


    and oor.shop_name = #{param.shopName}


    and oor.buyer_user_account = #{param.buyerUserAccount}


    and oor.order_id = #{param.orderId}


    and oor.return_add_time between #{param.returnStartTime} and #{param.returnFinishTime}


    and oob.payment_time between #{param.payStartTime} and #{param.payFinishTime}


    and oor.return_cash between #{param.returnMinCash} and #{param.returnMaxCash}

and oob.order_id = oor.order_id
order by oor.return_add_time desc
limit 1000

select a.order_id,b.shop_id,order_receiver_name,buyer_user_name,b.shop_name,a.goods_name,b.payment_time,sb.shop_tel, TIMESTAMPDIFF(hour,b.payment_time,now()) as time_diff,sb.shop_tel as orderSellerContact FROM ${database.prefix.order}hou_order_goods as a right join ${database.prefix.order}hou_order_base as b on b.order_id=a.order_id left join ${database.prefix.supplier}hou_shop_base sb on b.shop_id = sb.supplier_shop_id where b.order_status=3 and b.payment_time>='2019-01-01 00:00:00'
and a.order_id = #{param.orderId}
and a.shop_name like concat('%', #{param.shopName},'%')
and TIMESTAMPDIFF(hour,b.payment_time,now()) <= #{param.deliveryTime}
order by time_diff desc

select a.order_id,b.shop_id,order_receiver_name,buyer_user_name,b.shop_name,a.goods_name,b.payment_time,sb.shop_tel, TIMESTAMPDIFF(hour,b.payment_time,now()) as time_diff FROM ${database.prefix.order}hou_order_goods as a right join ${database.prefix.order}hou_order_base as b on b.order_id=a.order_id left join ${database.prefix.supplier}hou_shop_base sb on b.shop_id = sb.supplier_shop_id WHERE b.order_status=3 and b.payment_time>='2019-01-01 00:00:00'
and a.order_id = #{param.orderId}
and a.shop_name like concat('%', #{param.shopName},'%')
and TIMESTAMPDIFF(hour,b.payment_time,now()) <= #{param.deliveryTime}
order by time_diff desc

SELECT oor.return_state, oor.order_goods_num, oor.return_code, oor.return_cash, oor.return_commision_fee, oor.return_reason, oor.return_add_time, oor.return_shop_message, oor.return_shop_time, oor.order_id, oor.buyer_user_account, gmsb.shop_name, oob.payment_name, oob.payment_number, oob.order_payment_amount, oor.order_operator, oor.order_operator_time, oor.return_payment_voucher FROM ${database.prefix.order}hou_order_base oob, ${database.prefix.order}hou_order_return oor left join ${database.prefix.supplier}hou_shop_base gmsb on oor.shop_id = gmsb.supplier_shop_id WHERE oob.order_id = oor.order_id
and oor.return_type = 2
and oob.original_order is null
and oor.return_state= #{refundMap.returnState}
and oor.return_code = #{refundMap.returnCode}
and oor.shop_name like concat('%',#{refundMap.shopName},'%')
and oor.buyer_user_account like concat('%',#{refundMap.buyerUserAccount},'%')
and oor.order_id like concat('%',#{refundMap.orderId},'%')
and oor.return_add_time >=#{refundMap.returnStartTime}
and oor.return_add_time <= #{refundMap.returnFinishTime}
and oor.return_cash >= #{refundMap.returnMinCash}
and oor.return_cash <= #{refundMap.returnMaxCash}
order by oor.return_add_time desc

SELECT oor.return_code, oor.return_cash, oor.return_commision_fee, oor.return_reason, oor.return_add_time, oor.return_shop_message, oor.return_shop_time, oor.order_id, oor.buyer_user_account, gmsb.shop_name, oob.payment_name, oob.payment_number, oob.order_payment_amount, oor.return_state, oob.payment_time FROM ${database.prefix.order}hou_order_base oob, ${database.prefix.order}hou_order_return oor left join ${database.prefix.supplier}hou_shop_base gmsb on oor.shop_id=gmsb.supplier_shop_id WHERE oob.order_id = oor.order_id
