SELECT ob.shop_name, yor.return_code, yor.order_id, yor.order_id as orderNumber, yor.return_cash, a.trade_third_party_amount, a.trade_payment_recharge_card, a.trade_payment_amount, ob.buyer_user_name, yor.buyer_user_account, ob.payment_number, ob.payment_other_number, ob.order_payment_amount, ob.pay_code, yor.return_state, yor.return_add_time, yor.return_shop_time, yor.return_finish_time, yor.return_type, yor.order_goods_num FROM ${database.prefix.order}hou_order_return yor LEFT JOIN ${database.prefix.order}hou_order_base ob ON yor.order_id =ob.order_id LEFT JOIN ${database.prefix.payment}hou_pay_consume_trade a ON a.order_id = ob.order_id WHERE 1=1
AND ob.shop_name like concat('%',#{param.shopName},'%')
AND yor.order_id like concat('%',#{param.orderNumber},'%')
AND yor.return_code like concat('%',#{param.returnCode},'%')
AND yor.return_state = #{param.returnState}
AND ob.pay_code = #{param.payCode}
AND yor.return_type = #{param.returnType}
AND yor.return_add_time between #{param.returnAddTimeStart} and #{param.returnAddTimeEnd}
order by yor.return_add_time desc

SELECT ob.shop_name, yor.return_code, yor.order_id, yor.return_cash, a.trade_third_party_amount, a.trade_payment_recharge_card, a.trade_payment_amount, b.goods_name, b.goods_price, b.order_goods_num, b.order_goods_returnnum, b.order_shipping_code, ob.buyer_user_name, yor.buyer_user_account, ob.payment_number, ob.payment_other_number, ob.order_payment_amount, ob.pay_code, yor.return_state, yor.return_add_time, yor.return_shop_time, yor.return_finish_time, yor.return_type,yor.order_goods_num FROM ${database.prefix.order}hou_order_return yor LEFT join ${database.prefix.order}hou_order_goods b on b.order_id = yor.order_id LEFT join ${database.prefix.order}hou_order_base ob ON yor.order_id = ob.order_id LEFT JOIN ${database.prefix.payment}hou_pay_consume_trade a ON a.order_id = ob.order_id WHERE 1=1
AND ob.shop_name like concat('%',#{param.shopName},'%')
AND yor.order_id like concat('%',#{param.orderNumber},'%')
AND yor.return_code like concat('%',#{param.returnCode},'%')
AND yor.return_state = #{param.returnState}
AND ob.pay_code = #{param.payCode}
AND yor.return_type = #{param.returnType}
AND yor.return_add_time between #{param.returnAddTimeStart} and #{param.returnAddTimeEnd}
order by yor.return_add_time desc

SELECT oor.order_id,oor.return_cash,oor.return_code,oor.return_state,oor.return_add_time, oob.buyer_user_name,oog.drop_shipping,sob.order_refund_price as supper_refund_price,oor.expiration_time, sob.goods_payment_amount as supperPaymentAmount,oor.order_goods_num,oor.return_reason_id,oor.return_reason, rp.intervention_state,rp.processing_results,rp.processing_time,oob.order_payment_amount FROM ${database.prefix.order}hou_order_return oor LEFT join ${database.prefix.order}hou_order_base oob on oob.order_id = oor.order_id left join ${database.prefix.order}hou_order_goods oog on oob.order_id = oog.order_id LEFT join ${database.prefix.order}hou_order_supplier_base sob on sob.order_id = oor.order_id left join ${database.prefix.order}hou_order_return_platform rp on rp.order_id = oor.order_id where oor.return_method_status <> 3
and DATE_ADD(now(), INTERVAL 6 HOUR) >= oor.expiration_time
and oor.return_state = #{param.returnState}
and rp.intervention_state = #{param.platformIntervention}
and oor.return_code = #{param.returnCode}
and oor.order_id = #{param.orderId}
and oor.return_add_time between #{param.returnAddTime} and #{param.returnFinishTime}
and oor.return_method_status = #{param.returnMethodStatus}
and (( oob.shop_id = #{param.shopId} AND oob.original_order IS NULL) OR ( oob.deliver_shop_id = #{param.shopId} AND oob.original_order IS NOT NULL ) )
and (( oob.shop_id = #{param.shopId} AND oob.original_order IS NULL) OR ( oob.deliver_shop_id = #{param.shopId} AND oob.original_order IS NOT NULL ) )
group by oob.order_id order by oor.return_add_time desc

SELECT oob.order_receiver_contact,oob.order_shipping_code,oor.return_cash,oob.shop_id,oob.shop_name, oor.order_id, oor.return_code, oor.return_type, oor.return_add_time, oor.return_state, oor.return_message,oor.return_reason, oor.return_shipping_code,oor.order_goods_num,oog.drop_shipping,sob.order_return_price as supper_return_price,sob.goods_payment_amount as supper_payment_amount, rp.intervention_state,oob.order_payment_amount FROM ${database.prefix.order}hou_order_return oor LEFT join ${database.prefix.order}hou_order_base oob on oob.order_id = oor.order_id left join ${database.prefix.order}hou_order_goods oog on oob.order_id = oog.order_id left join ${database.prefix.order}hou_order_supplier_base sob on sob.order_id = oor.order_id left join ${database.prefix.order}hou_order_return_platform rp on rp.order_id = oor.order_id where oor.return_method_status = 3
and DATE_ADD(now(), INTERVAL 6 HOUR) >= oor.expiration_time and oor.return_state = 1
and oor.return_state = #{param.returnState}
and oor.order_id = #{param.orderId}
and oor.return_code = #{param.returnCode}
and rp.intervention_state = #{param.platformIntervention}
and oor.return_type = #{param.returnType}
and oor.return_add_time between #{param.returnAddTime} and #{param.returnFinishTime}
and ((oob.shop_id = #{param.shopId} AND oob.original_order IS NULL) or( oob.deliver_shop_id = #{param.shopId} AND oob.original_order IS NOT NULL))
and ((oob.shop_id = #{param.shopId} AND oob.original_order IS NULL) or( oob.deliver_shop_id = #{param.shopId} AND oob.original_order IS NOT NULL)) and oor.return_type = 2
GROUP BY oor.order_id ORDER BY oor.return_add_time desc

